import { describe, expect, it } from "vitest";
import {
  getRoleShortcutLimit,
  roleShortcutError,
  normalizeRole,
} from "@/lib/roles";
import { preferredRolesSchema } from "@/lib/validation";

const legacy = Array.from({ length: 20 }, (_, i) => `Role ${i}`);
describe("saved role shortcuts", () => {
  it.each([
    ["FREE", 2],
    ["PAID", 8],
  ] as const)("limits %s to %i arbitrary shortcuts", (plan, limit) => {
    const roles = legacy.slice(0, limit);
    expect(getRoleShortcutLimit(plan)).toBe(limit);
    expect(roleShortcutError(plan, roles, [])).toBeUndefined();
    expect(roleShortcutError(plan, [...roles, "Extra"], [])).toContain(
      `${limit}`,
    );
    expect(roleShortcutError(plan, [], roles)).toBeUndefined();
  });
  it("retains, reorders and removes legacy shortcuts but blocks replacements above the limit", () => {
    for (const plan of ["FREE", "PAID"] as const) {
      expect(roleShortcutError(plan, legacy, legacy)).toBeUndefined();
      expect(
        roleShortcutError(plan, legacy.slice(0, 10).reverse(), legacy),
      ).toBeUndefined();
      expect(
        roleShortcutError(plan, [...legacy.slice(0, 9), "Extra"], legacy),
      ).toBeDefined();
      expect(roleShortcutError(plan, ["New title"], legacy)).toBeUndefined();
    }
  });
  it("normalizes retained shortcuts and rejects duplicate or invalid text", () => {
    expect(normalizeRole("  Product   DESIGNER ")).toBe("product designer");
    expect(
      roleShortcutError(
        "FREE",
        legacy.map((role) => role.toUpperCase()),
        legacy,
      ),
    ).toBeUndefined();
    expect(preferredRolesSchema.parse([])).toEqual([]);
    expect(preferredRolesSchema.parse(["  Researcher  "])).toEqual([
      "Researcher",
    ]);
    for (const roles of [[" "], ["Engineer", " ENGINEER "], ["x".repeat(161)]])
      expect(preferredRolesSchema.safeParse(roles).success).toBe(false);
    expect(preferredRolesSchema.parse(legacy)).toHaveLength(20);
  });
});
